.im-sheet {
	display: block;
	position: fixed;
	z-index: 1351;
	width: 100%;
	height: 100%;
	top: 0;
	right: 0;
	bottom: 0;
	left: 0;
	overflow: hidden;
	background: rgba(0, 0, 0, 0.6);
}
.im-sheet .im-sheet-content {
	display: block;
	position: fixed;
	top: 100%;
	bottom: auto;
	background: #fff;
	border-radius: 8px 8px 0 0;
	padding: 0;
	width: 100%;
	-webkit-transition: top 200ms ease;
	-o-transition:      top 200ms ease;
	transition: top 200ms ease;
